//! Java JNI demangling corpus gate.
//!
//! Reads the corpora under `refs/jni/corpus/`:
//!
//! - `jdk21-javac-h.txt` — `symbol<TAB>display` rows generated by
//!   `refs/jni/extract-jni-symbols.sh` from `javac -h` headers of a fixture
//!   project (JDK 21.0.13.1). The symbol column is javac's own mangling and the
//!   display column is built from `javap -p -s` output, so neither side comes
//!   from this crate.
//! - `hand.txt` — hand-authored rows for spec-defined shapes that `javac` does
//!   not emit in the fixture (single-component classes, escaped characters in
//!   the class part, `_0xxxx` escapes in a class name).
//! - `rejected.txt` — hand-authored malformed names: truncated and malformed
//!   escapes, unpaired surrogates, malformed descriptors, `JNI_` helpers and
//!   ordinary C names that merely start with `Java_`.
//! - `jdk21-libraries.txt` — every `Java_` symbol exported by the JDK's own
//!   native libraries. There is no oracle for their display text, so they are a
//!   coverage corpus: each must parse, be claimed as JNI, and re-encode to the
//!   original symbol under the mangling rules.
//!
//! `refs/` is excluded from the published crate, so every test skips gracefully
//! when the corpus is absent. The gate is exact equality: a name that prints
//! anything other than its expected text fails, and nothing is compared
//! loosely.

#![cfg(feature = "jni")]

use std::path::Path;

use demangle::{Demangler, Scheme};

/// Rows generated from `javac -h` headers of the fixture project.
const GENERATED: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/refs/jni/corpus/jdk21-javac-h.txt");
/// Hand-authored positive rows.
const HAND: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/refs/jni/corpus/hand.txt");
/// Hand-authored malformed names.
const REJECTED: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/refs/jni/corpus/rejected.txt");
/// JNI names exported by the JDK's own native libraries.
const LIBRARIES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/refs/jni/corpus/jdk21-libraries.txt");

/// Measured floors. Raise them when coverage improves; never lower them.
const GENERATED_ROWS: usize = 42;
const HAND_ROWS: usize = 16;
const REJECTED_ROWS: usize = 35;
const LIBRARY_NAMES: usize = 1_037;

/// Read a `symbol<TAB>display` corpus, or `None` when `refs/` is absent.
fn rows(path: &str) -> Option<Vec<(String, String)>> {
    let text = std::fs::read_to_string(path).ok()?;
    let mut rows = Vec::new();
    for line in text.lines() {
        if line.is_empty() {
            continue;
        }
        let (symbol, expected) = line
            .split_once('\t')
            .unwrap_or_else(|| panic!("{path}: row without a tab: {line:?}"));
        rows.push((symbol.to_owned(), expected.to_owned()));
    }
    Some(rows)
}

/// Read a one-symbol-per-line corpus, or `None` when `refs/` is absent.
fn names(path: &str) -> Option<Vec<String>> {
    let text = std::fs::read_to_string(path).ok()?;
    Some(
        text.lines()
            .filter(|line| !line.is_empty())
            .map(str::to_owned)
            .collect(),
    )
}

/// Demangle one symbol and compare it exactly.
fn check(symbol: &str, expected: &str) {
    let demangler = Demangler::new();
    assert_eq!(
        Scheme::detect(symbol),
        Scheme::Jni,
        "{symbol}: not detected as JNI"
    );
    let demangled = demangler
        .demangle(symbol)
        .unwrap_or_else(|error| panic!("{symbol}: {error}"));
    assert_eq!(demangled.scheme(), Scheme::Jni, "{symbol}");
    assert_eq!(demangled.language(), demangle::Language::Java, "{symbol}");
    assert_eq!(demangled.to_string(), expected, "{symbol}");
}

#[test]
fn generated_names_match_exactly() {
    let Some(rows) = rows(GENERATED) else {
        return;
    };
    assert_eq!(
        rows.len(),
        GENERATED_ROWS,
        "generated corpus row count changed"
    );
    for (symbol, expected) in &rows {
        check(symbol, expected);
    }
}

#[test]
fn hand_names_match_exactly() {
    let Some(rows) = rows(HAND) else {
        return;
    };
    assert_eq!(rows.len(), HAND_ROWS, "hand corpus row count changed");
    for (symbol, expected) in &rows {
        check(symbol, expected);
    }
}

#[test]
fn rejected_names_are_not_jni() {
    let Some(names) = names(REJECTED) else {
        return;
    };
    assert_eq!(
        names.len(),
        REJECTED_ROWS,
        "rejected corpus row count changed"
    );
    for name in &names {
        assert_ne!(Scheme::detect(name), Scheme::Jni, "{name}: claimed as JNI");
        assert!(
            demangle::jni::parse(name).is_err(),
            "{name}: parsed as a JNI name"
        );
    }
}

#[test]
fn generated_corpus_is_claimed_before_legacy_cpp() {
    // A long name contains `__`, which the legacy C++ dialects would otherwise
    // accept as a nested-name separator.
    let Some(rows) = rows(GENERATED) else {
        return;
    };
    let long: Vec<&String> = rows
        .iter()
        .map(|(symbol, _)| symbol)
        .filter(|symbol| symbol.contains("__"))
        .collect();
    assert!(!long.is_empty(), "generated corpus has no long names");
    for symbol in long {
        assert_eq!(Scheme::detect(symbol), Scheme::Jni, "{symbol}");
    }
}

#[cfg(feature = "cpp-gnu-v2")]
#[test]
fn long_names_are_not_legacy_cpp() {
    for symbol in [
        "Java_com_example_Foo_bar__I",
        "Java_com_example_Foo_bar___3Ljava_lang_String_2I",
        "Java_com_example_Foo_under_1score__",
    ] {
        assert_eq!(Scheme::detect(symbol), Scheme::Jni, "{symbol}");
        let demangled = Demangler::new().demangle(symbol).unwrap();
        assert_eq!(demangled.scheme(), Scheme::Jni, "{symbol}");
    }
}

#[cfg(feature = "cpp-gnu-v2")]
#[test]
fn jni_helpers_stay_c() {
    for symbol in ["JNI_OnLoad", "JNI_CreateJavaVM", "JNI_GetCreatedJavaVMs"] {
        assert_eq!(Scheme::detect(symbol), Scheme::C, "{symbol}");
    }
}

/// Encode one decoded name with the JNI escaping rules.
///
/// This is the inverse of the parser's decoding, written from the specification
/// rather than from the parser: `.` is a separator, `_` is `_1`, `;` is `_2`,
/// `[` is `_3`, an ASCII alphanumeric is literal and every other character is
/// `_0xxxx` per UTF-16 code unit.
fn encode_name(name: &str, out: &mut String) {
    use std::fmt::Write as _;

    for character in name.chars() {
        match character {
            '.' => out.push('_'),
            '_' => out.push_str("_1"),
            ';' => out.push_str("_2"),
            '[' => out.push_str("_3"),
            character if character.is_ascii_alphanumeric() => out.push(character),
            character => {
                let mut units = [0_u16; 2];
                for unit in character.encode_utf16(&mut units) {
                    write!(out, "_0{unit:04x}").unwrap();
                }
            }
        }
    }
}

/// The descriptor byte of a primitive type.
fn primitive_byte(primitive: demangle::jni::Primitive) -> char {
    match primitive {
        demangle::jni::Primitive::Byte => 'B',
        demangle::jni::Primitive::Char => 'C',
        demangle::jni::Primitive::Double => 'D',
        demangle::jni::Primitive::Float => 'F',
        demangle::jni::Primitive::Int => 'I',
        demangle::jni::Primitive::Long => 'J',
        demangle::jni::Primitive::Short => 'S',
        demangle::jni::Primitive::Boolean => 'Z',
    }
}

/// Re-encode a parsed name with the JNI escaping rules.
fn encode(ast: &demangle::jni::Ast<'_>) -> String {
    let mut symbol = String::from("Java_");
    encode_name(ast.class(), &mut symbol);
    symbol.push('_');
    encode_name(ast.method(), &mut symbol);
    if let Some(descriptor) = ast.descriptor() {
        symbol.push_str("__");
        for argument in descriptor.args() {
            for _ in 0..argument.dimensions() {
                symbol.push_str("_3");
            }
            match argument.element() {
                demangle::jni::Element::Primitive(primitive) => {
                    symbol.push(primitive_byte(*primitive));
                }
                demangle::jni::Element::Object(name) => {
                    symbol.push('L');
                    encode_name(name, &mut symbol);
                    symbol.push_str("_2");
                }
            }
        }
    }
    symbol
}

#[test]
fn library_names_parse_and_reencode() {
    let Some(names) = names(LIBRARIES) else {
        return;
    };
    assert_eq!(
        names.len(),
        LIBRARY_NAMES,
        "library corpus row count changed"
    );
    for name in &names {
        let ast = demangle::jni::parse(name).unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(Scheme::detect(name), Scheme::Jni, "{name}");
        assert!(!ast.class().is_empty(), "{name}");
        assert!(!ast.method().is_empty(), "{name}");
        // Decoding loses nothing: the mangling rules reproduce the symbol.
        assert_eq!(&encode(&ast), name, "{name}");
    }
}

#[test]
fn generated_names_reencode() {
    let Some(rows) = rows(GENERATED) else {
        return;
    };
    for (symbol, _) in &rows {
        let ast = demangle::jni::parse(symbol).unwrap_or_else(|error| panic!("{symbol}: {error}"));
        assert_eq!(&encode(&ast), symbol, "{symbol}");
    }
}

#[test]
fn corpus_files_are_present_or_absent_together() {
    let present = Path::new(GENERATED).exists();
    assert_eq!(present, Path::new(HAND).exists());
    assert_eq!(present, Path::new(REJECTED).exists());
    assert_eq!(present, Path::new(LIBRARIES).exists());
}
